import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfCurso = () => {
  const { id } = useParams(); // Captura o ID do curso pela URL
  const [curso, setCurso] = useState({
    nome: "",
    nivel: "",
    periodo: "",
    area: "",
    professor: "",
    alunos: [], // Inicializando alunos como um array vazio
  });
  const [alunos, setAlunos] = useState([]); // Estado para armazenar lista de alunos cadastrados
  const [professores, setProfessores] = useState([]); // Estado para armazenar lista de professores
  const [editMode, setEditMode] = useState(false); // Controle do modo de edição
  const [selectedAlunos, setSelectedAlunos] = useState([]); // Alunos selecionados para o curso

  // Função para buscar as informações do curso e professores
  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);
          setSelectedAlunos(dados.alunos || []); // Preencher alunos selecionados ao buscar o curso (garantir que não seja undefined)
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchAlunos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setAlunos(dados || []); // Garantir que dados não sejam undefined
        }
      } catch (error) {
        console.error("Erro na requisição de alunos:", error);
      }
    };

    const fetchProfessores = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessores(dados || []); // Garantir que dados não sejam undefined
        }
      } catch (error) {
        console.error("Erro na requisição de professores:", error);
      }
    };

    fetchCurso();
    fetchAlunos();
    fetchProfessores();
  }, [id]);

  // Função para ativar o modo de edição
  const handleEditClick = () => setEditMode(true);

  // Função para cancelar a edição
  const handleCancelClick = () => setEditMode(false);

  // Função para salvar as edições do curso
  const handleSaveClick = async () => {
    if (!curso) return;

    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...curso, alunos: selectedAlunos }), // Enviar alunos selecionados
      });

      if (resposta.ok) {
        setCurso({ ...curso, alunos: selectedAlunos }); // Atualizar os alunos do curso
        setEditMode(false);
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Função para atualizar os alunos selecionados
  const handleAlunoSelect = (e) => {
    const aluno = e.target.value;
    const isChecked = e.target.checked;

    setSelectedAlunos((prevSelectedAlunos) => {
      if (isChecked) {
        return [...prevSelectedAlunos, aluno];
      } else {
        return prevSelectedAlunos.filter(
          (selectedAluno) => selectedAluno !== aluno
        );
      }
    });
  };

  // Função para atualizar o professor
  const handleProfessorChange = (e) => {
    setCurso({ ...curso, professor: e.target.value });
  };

  // Verificar se todos os dados necessários estão carregados
  if (
    !curso ||
    !alunos ||
    !professores ||
    !Array.isArray(alunos) ||
    !Array.isArray(professores)
  ) {
    return <p className="text-center mt-4">Carregando...</p>; // Garantir que os dados estejam carregados corretamente
  }

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistprof">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{curso.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={handleEditClick}>
            Editar
          </button>
        )}
      </div>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        {/* Informação do curso */}
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informações do Curso</h4>
          <p>
            <strong>{curso.nome}</strong>
          </p>
          <p>{curso.nivel}</p>
          <p>{curso.periodo}</p>
          <p>{curso.area}</p>
        </div>

        {/* Formulário de edição */}
        <div className="w-50 ps-4">
          <div className="mb-3">
            <label className="fw-bold">Professor</label>
            <div className="input-group">
              <select
                className="form-control"
                name="professor"
                value={curso.professor}
                onChange={handleProfessorChange}
                disabled={!editMode}
              >
                <option value="">Selecione um professor</option>
                {professores.map((professor) => (
                  <option key={professor.id} value={professor.nome}>
                    {professor.nome}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <label className="fw-bold">Alunos</label>
          {editMode ? (
            <div>
              {alunos.map((aluno) => (
                <div key={aluno.id} className="form-check">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    value={aluno.nome}
                    checked={selectedAlunos.includes(aluno.nome)}
                    onChange={handleAlunoSelect}
                  />
                  <label className="form-check-label">{aluno.nome}</label>
                </div>
              ))}
            </div>
          ) : (
            <ul>
              {curso.alunos.map((aluno, index) => (
                <li key={index}>{aluno}</li>
              ))}
            </ul>
          )}

          {editMode && (
            <div className="d-flex justify-content-between mt-3">
              <button className="btn btn-danger" onClick={handleCancelClick}>
                Cancelar
              </button>
              <button className="btn btn-primary" onClick={handleSaveClick}>
                Salvar
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdmInfCurso;
